"use client";
import {
  useGlobalChat,
  useInfiniteCanvas,
  useInspiration,
} from "@/hooks/use-canvas";
import React, { useState, useEffect } from "react";
import TextSidebar from "./text-sidebar";
import { cn } from "@/lib/utils";
import ShapeRenderer from "./shapes";
import { RectanglePreview } from "./shapes/rectangle/preview";
import { FramePreview } from "./shapes/frame/preview";
import { EllipsePreview } from "./shapes/ellipse/preview";
import { NotePreview } from "./shapes/note/preview";
import { ArrowPreview } from "./shapes/arrow/preview";
import { LinePreview } from "./shapes/line/preview";
import { FreeDrawStrokePreview } from "./shapes/stroke/preview";
import { SelectionOverlay } from "./shapes/selection";
import InspirationSidebar from "./shapes/inspiration-sidebar";
import ChatWindow from "./shapes/generatedui/chat";
import { useAppDispatch, useAppSelector } from "@/redux/store";
import {
  loadStyleGuideStart,
  loadStyleGuideSuccess,
  loadStyleGuideFailure,
} from "@/redux/slice/style-guide";
import { useTokenInjection } from "@/hooks/use-token-injection";
import { setTranslate } from "@/redux/slice/viewport";
import Minimap from "./minimap";
import { useSearchParams } from "next/navigation";
import { Shape } from "@/redux/slice/shapes";
import { calculateArrowHead } from "@/lib/shape-utils";

const InfiniteCanvas = () => {
  const dispatch = useAppDispatch();
  const searchParams = useSearchParams();
  const projectId = searchParams.get("project") || "";

  // Broadcast design token updates to all generated-UI iframes
  useTokenInjection();

  const {
    viewport,
    shapes,
    currentTool,
    selectedShapes,
    onPointerDown,
    onPointerMove,
    onPointerUp,
    onPointerCancel,
    attachCanvasRef,
    getDraftShape,
    getFreeDrawPoints,
    isSidebarOpen,
    hasSelectedText,
    connectorDrag,
    laserPoints,
    laserCursor,
  } = useInfiniteCanvas();

  const { isInspirationOpen, closeInspiration, toggleInspiration } =
    useInspiration();

  const {
    isChatOpen,
    setIsChatOpen,
    activeGeneratedUIId,
    closeChat,
    toggleChat,
    generateWorkflow,
    exportDesign,
  } = useGlobalChat();

  useEffect(() => {
    if (!projectId) return;

    const loadStyleGuide = async () => {
      dispatch(loadStyleGuideStart());
      try {
        const res = await fetch(`/api/projects/${projectId}/style-guide`);
        if (res.ok) {
          const data = await res.json();
          dispatch(loadStyleGuideSuccess(data.styleGuide));
        } else {
          dispatch(loadStyleGuideFailure("Failed to load style guide"));
        }
      } catch (err) {
        dispatch(loadStyleGuideFailure("Failed to load style guide"));
      }
    };

    loadStyleGuide();
  }, [dispatch, projectId]);

  const draftShape = getDraftShape();
  const freeDrawPoints = getFreeDrawPoints();

  // Canvas element size for minimap
  const [canvasSize, setCanvasSize] = React.useState({ width: 1200, height: 800 });
  const canvasContainerRef = React.useRef<HTMLDivElement>(null);
  React.useEffect(() => {
    const el = canvasContainerRef.current;
    if (!el) return;
    const observer = new ResizeObserver((entries) => {
      for (const entry of entries) {
        setCanvasSize({ width: entry.contentRect.width, height: entry.contentRect.height });
      }
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  const handleMinimapNavigate = React.useCallback(
    (worldX: number, worldY: number) => {
      // Center the viewport on the clicked world position
      dispatch(
        setTranslate({
          x: canvasSize.width / 2 - worldX * viewport.scale,
          y: canvasSize.height / 2 - worldY * viewport.scale,
        })
      );
    },
    [dispatch, viewport.scale, canvasSize]
  );

  const handleRef = React.useCallback(
    (el: HTMLDivElement | null) => {
      attachCanvasRef(el);
      (canvasContainerRef as React.MutableRefObject<HTMLDivElement | null>).current = el;
    },
    [attachCanvasRef]
  );

  return (
    <div className="relative flex h-screen w-screen overflow-hidden pt-16 bg-background">
      <TextSidebar isOpen={isSidebarOpen && hasSelectedText} />
      <InspirationSidebar
        isOpen={isInspirationOpen}
        onClose={closeInspiration}
      />

      {/* Center Canvas */}
      <div
        ref={handleRef}
        role="application"
        aria-label="Infinite drawing canvas"
        className={cn(
          "relative flex-1 h-full overflow-hidden select-none z-0 bg-background",
          {
            "cursor-grabbing": viewport.mode === "panning",
            "cursor-grab":
              viewport.mode === "shiftPanning" ||
              (currentTool === "pan" && viewport.mode === "idle"),
            "cursor-eraser":
              currentTool === "eraser" && viewport.mode === "idle",
            "cursor-crosshair":
              currentTool !== "select" &&
              currentTool !== "pan" &&
              currentTool !== "eraser" &&
              currentTool !== "laser" &&
              viewport.mode === "idle",
            "cursor-none": currentTool === "laser" && viewport.mode === "idle",
            "cursor-default":
              currentTool === "select" && viewport.mode === "idle",
          },
        )}
        style={{
          touchAction: "none",
          backgroundImage:
            "radial-gradient(circle, var(--canvas-grid) 1px, transparent 1px)",
          backgroundSize: `${20 * viewport.scale}px ${20 * viewport.scale}px`,
          backgroundPosition: `${viewport.translate.x}px ${viewport.translate.y}px`,
        }}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerCancel}
        onContextMenu={(e) => e.preventDefault()}
        draggable={false}
      >
        <div
          className="absolute origin-top-left pointer-events-none z-10"
          style={{
            transform: `translate3d(${viewport.translate.x}px, ${viewport.translate.y}px, 0) scale(${viewport.scale})`,
            transformOrigin: "0 0",
            willChange: "transform",
          }}
        >
          {shapes.map((shape: Shape) => (
            <ShapeRenderer
              key={shape.id}
              shape={shape}
              toggleInspiration={toggleInspiration}
              toggleChat={toggleChat}
              generateWorkflow={generateWorkflow}
              exportDesign={exportDesign}
            />
          ))}
          {shapes.map((shape: Shape) => (
            <SelectionOverlay
              key={`selection-${shape.id}`}
              shape={shape}
              isSelected={!!selectedShapes[shape.id]}
            />
          ))}
          {draftShape && draftShape.type === "frame" && (
            <FramePreview
              startWorld={draftShape.startWorld}
              currentWorld={draftShape.currentWorld}
            />
          )}
          {draftShape && draftShape.type === "rect" && (
            <RectanglePreview
              startWorld={draftShape.startWorld}
              currentWorld={draftShape.currentWorld}
            />
          )}
          {draftShape && draftShape.type === "note" && (
            <NotePreview
              startWorld={draftShape.startWorld}
              currentWorld={draftShape.currentWorld}
            />
          )}
          {draftShape && draftShape.type === "ellipse" && (
            <EllipsePreview
              startWorld={draftShape.startWorld}
              currentWorld={draftShape.currentWorld}
            />
          )}
          {draftShape && draftShape.type === "arrow" && (
            <ArrowPreview
              startWorld={draftShape.startWorld}
              currentWorld={draftShape.currentWorld}
            />
          )}
          {draftShape && draftShape.type === "line" && (
            <LinePreview
              startWorld={draftShape.startWorld}
              currentWorld={draftShape.currentWorld}
            />
          )}
          {currentTool === "freedraw" && freeDrawPoints.length > 1 && (
            <FreeDrawStrokePreview points={freeDrawPoints} />
          )}
          {laserPoints && laserPoints.length > 1 && (
            <svg className="absolute top-0 left-0 w-full h-full overflow-visible pointer-events-none z-50">
              <defs>
                <filter
                  id="laser-glow"
                  x="-50%"
                  y="-50%"
                  width="200%"
                  height="200%"
                >
                  <feGaussianBlur stdDeviation="4" result="blur" />
                  <feMerge>
                    <feMergeNode in="blur" />
                    <feMergeNode in="SourceGraphic" />
                  </feMerge>
                </filter>
              </defs>
              <g filter="url(#laser-glow)">
                {laserPoints.slice(0, -1).map((p, idx) => {
                  const pNext = laserPoints[idx + 1];
                  const now = Date.now();
                  const avgTime = (p.time + pNext.time) / 2;
                  const age = now - avgTime;
                  const opacity = Math.max(0, 1 - age / 1000);
                  if (opacity <= 0) return null;
                  return (
                    <line
                      key={`laser-${idx}-${p.time}`}
                      x1={p.x}
                      y1={p.y}
                      x2={pNext.x}
                      y2={pNext.y}
                      stroke="#ff3b30"
                      strokeWidth={6 * opacity}
                      strokeLinecap="round"
                      opacity={opacity}
                    />
                  );
                })}
              </g>
            </svg>
          )}

          {draftShape && draftShape.type === "selection" && (
            <svg
              className="absolute pointer-events-none overflow-visible z-50"
              style={{
                left: Math.min(
                  draftShape.startWorld.x,
                  draftShape.currentWorld.x,
                ),
                top: Math.min(
                  draftShape.startWorld.y,
                  draftShape.currentWorld.y,
                ),
                width: Math.abs(
                  draftShape.currentWorld.x - draftShape.startWorld.x,
                ),
                height: Math.abs(
                  draftShape.currentWorld.y - draftShape.startWorld.y,
                ),
              }}
            >
              <rect
                x={0}
                y={0}
                width={Math.abs(
                  draftShape.currentWorld.x - draftShape.startWorld.x,
                )}
                height={Math.abs(
                  draftShape.currentWorld.y - draftShape.startWorld.y,
                )}
                fill="rgba(59, 130, 246, 0.15)"
                stroke="#3b82f6"
                strokeWidth={1.5}
                className="animate-marching-ants"
              />
            </svg>
          )}
          {connectorDrag && (
            <svg className="absolute overflow-visible pointer-events-none z-50">
              <line
                x1={connectorDrag.startPoint.x}
                y1={connectorDrag.startPoint.y}
                x2={connectorDrag.currentPoint.x}
                y2={connectorDrag.currentPoint.y}
                stroke="#db2800"
                strokeWidth={2}
                strokeLinecap="round"
                className="animate-connector-flow"
              />
              {(() => {
                const arrowHead = calculateArrowHead(
                  connectorDrag.startPoint.x,
                  connectorDrag.startPoint.y,
                  connectorDrag.currentPoint.x,
                  connectorDrag.currentPoint.y,
                  10,
                );
                return (
                  <polygon
                    points={`${connectorDrag.currentPoint.x},${connectorDrag.currentPoint.y} ${arrowHead.x1},${arrowHead.y1} ${arrowHead.x2},${arrowHead.y2}`}
                    fill="#db2800"
                  />
                );
              })()}
            </svg>
          )}
        </div>

        {currentTool === "laser" && laserCursor && (
          <div
            className="absolute pointer-events-none rounded-full bg-red-500 w-4 h-4 shadow-[0_0_12px_#ef4444] z-50 animate-pulse border border-white"
            style={{
              left: laserCursor.x - 8,
              top: laserCursor.y - 8,
            }}
          />
        )}
      </div>

      {/* Right Chat Sidebar */}
      {activeGeneratedUIId && isChatOpen && (
        <ChatWindow
          generatedUIId={activeGeneratedUIId}
          isOpen={isChatOpen}
          onClose={closeChat}
        />
      )}

      {/* Minimap */}
      <Minimap
        viewport={viewport}
        canvasSize={canvasSize}
        onNavigate={handleMinimapNavigate}
      />
    </div>
  );
};

export default InfiniteCanvas;

"use client";
import React, { useEffect, useState, useRef } from "react";
import { useSearchParams } from "next/navigation";
import {
  Search,
  ChevronDown,
  Sparkles,
  Check,
  Image as ImageIcon,
  CheckCircle,
} from "lucide-react";
import { toast } from "sonner";

interface Model {
  id: string;
  name: string;
  provider: string;
  rawId: string;
  supportsVision?: boolean;
}

export default function ModelSelector() {
  const searchParams = useSearchParams();
  const projectId = searchParams.get("project");

  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState("");
  const [models, setModels] = useState<Model[]>([]);
  const [selectedModel, setSelectedModel] = useState<string>("");
  const [loading, setLoading] = useState(true);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Fetch models and current selection
    async function load() {
      if (!projectId) return;
      try {
        setLoading(true);
        // 1. Fetch available models
        const modelsRes = await fetch("/api/models");
        if (!modelsRes.ok) throw new Error("Failed to load models list");
        const modelsData = await modelsRes.json();
        setModels(modelsData.models || []);

        // 2. Fetch selected model
        const selectRes = await fetch(
          `/api/models/select?projectId=${projectId}`,
        );
        if (selectRes.ok) {
          const selectData = await selectRes.json();
          if (selectData.model) {
            setSelectedModel(selectData.model);
          } else {
            // Default fallback
            const fallback =
              process.env.NEXT_PUBLIC_OPENUI_FALLBACK_MODEL ||
              "openrouter/anthropic/claude-opus-4";
            setSelectedModel(fallback);
          }
        }
      } catch (err) {
        console.error("Error loading model selector data:", err);
        toast.error("Failed to load AI models");
      } finally {
        setLoading(false);
      }
    }
    load();
  }, [projectId]);

  // Close dropdown on click outside or when an iframe (canvas preview) gains focus
  useEffect(() => {
    function handleClickOutside(event: Event) {
      if (
        dropdownRef.current &&
        !dropdownRef.current.contains(event.target as Node)
      ) {
        setIsOpen(false);
      }
    }

    function handleBlur() {
      // Check after one frame if the new active element is an iframe
      setTimeout(() => {
        if (
          document.activeElement &&
          document.activeElement.tagName === "IFRAME"
        ) {
          setIsOpen(false);
        }
      }, 0);
    }

    document.addEventListener("mousedown", handleClickOutside);
    document.addEventListener("pointerdown", handleClickOutside);
    window.addEventListener("blur", handleBlur);

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.removeEventListener("pointerdown", handleClickOutside);
      window.removeEventListener("blur", handleBlur);
    };
  }, []);

  const handleSelect = async (modelId: string, provider: string) => {
    if (!projectId) return;
    try {
      setSelectedModel(modelId);
      setIsOpen(false);
      const res = await fetch("/api/models/select", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          projectId,
          provider,
          model: modelId,
        }),
      });
      if (!res.ok) {
        const errData = await res.json().catch(() => ({}));
        throw new Error(
          errData.message || errData.error || "Failed to save selection",
        );
      }
      const modelName = modelId.split("/").pop() || "";
      const capitalized = modelName.replace(/(^\w|-\w)/g, (m) => m.toUpperCase());
      toast.success(`Active model updated: ${capitalized}`);
    } catch (err: any) {
      console.error(err);
      toast.error(`Failed to save model selection: ${err.message || err}`);
    }
  };

  // Group and filter models
  const filteredModels = models.filter(
    (m) =>
      m.name.toLowerCase().includes(search.toLowerCase()) ||
      m.id.toLowerCase().includes(search.toLowerCase()),
  );

  const grouped: Record<string, Model[]> = {};
  filteredModels.forEach((m) => {
    if (!grouped[m.provider]) grouped[m.provider] = [];
    grouped[m.provider].push(m);
  });

  const formatModelName = (name: string, provider: string) => {
    if (provider === "openrouter" && name.includes(":")) {
      return name.split(":").slice(1).join(":").trim();
    }
    return name;
  };

  const getDisplayName = (id: string) => {
    const found = models.find((m) => m.id === id);
    if (found) return formatModelName(found.name, found.provider);
    return id.split("/").pop() || id;
  };

  // Sort groups: Provider containing selected model comes first
  const sortedGroupedEntries = Object.entries(grouped).sort(
    ([provA, modelsA], [provB, modelsB]) => {
      const hasSelectedA = modelsA.some((m) => m.id === selectedModel);
      const hasSelectedB = modelsB.some((m) => m.id === selectedModel);
      if (hasSelectedA && !hasSelectedB) return -1;
      if (!hasSelectedA && hasSelectedB) return 1;
      return 0;
    },
  );

  // Sort models in a group: Selected model comes first
  const getSortedModels = (providerModels: Model[]) => {
    return [...providerModels].sort((a, b) => {
      if (a.id === selectedModel) return -1;
      if (b.id === selectedModel) return 1;
      return 0;
    });
  };

  if (!projectId) return null;

  return (
    <div className="relative inline-block text-left" ref={dropdownRef}>
      <button
        onClick={() => setIsOpen(!isOpen)}
        disabled={loading}
        className="flex items-center gap-2 rounded-full px-4 h-8 text-xs font-semibold border border-border bg-card text-foreground hover:bg-secondary transition disabled:opacity-50 shadow-3xs cursor-pointer"
      >
        <Sparkles className="size-3.5 text-primary" />
        <span className="max-w-[130px] truncate capitalize">
          {loading ? "Loading AI models..." : getDisplayName(selectedModel)}
        </span>
        <ChevronDown className="size-3.5 opacity-85" />
      </button>

      {isOpen && (
        <div className="absolute right-0 mt-2 w-82 rounded-2xl border border-border bg-card shadow-lg z-100 overflow-hidden">
          <div className="p-3 border-b border-border/60 flex items-center gap-2">
            <Search className="size-4 text-muted-foreground/80" />
            <input
              type="text"
              placeholder="Search models..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="bg-transparent border-none outline-none text-xs text-foreground w-full placeholder-muted-foreground/50"
              autoFocus
            />
          </div>

          <div className="max-h-80 overflow-y-auto p-2">
            {sortedGroupedEntries.length === 0 ? (
              <div className="p-4 text-center text-xs text-muted-foreground">
                No models found!
              </div>
            ) : (
              sortedGroupedEntries.map(([provider, providerModels]) => (
                <div key={provider} className="mb-3">
                  <div className="px-3 py-1 text-[10px] underline underline-offset-1 font-bold text-muted-foreground uppercase tracking-wider">
                    {provider}
                  </div>
                  <div className="mt-1 space-y-1">
                    {getSortedModels(providerModels).map((m) => (
                      <button
                        key={m.id}
                        onClick={() => handleSelect(m.id, m.provider)}
                        className={`w-full flex items-center justify-between px-3 py-1.5 rounded-lg text-xs text-left transition cursor-pointer border ${
                          selectedModel === m.id
                            ? "bg-primary/10 text-primary border-primary/20 font-bold"
                            : "text-foreground hover:bg-secondary border-transparent hover:text-foreground"
                        }`}
                      >
                        <div className="flex flex-col min-w-0">
                          <span className="truncate text-sm capitalize font-semibold">
                            {formatModelName(m.name, m.provider)}
                          </span>
                          <span className="text-xs text-foreground/50 wrap-break-word">
                            {m.id}
                          </span>
                        </div>
                        <div className="flex items-center gap-1.5 shrink-0 ml-2">
                          {m.supportsVision && selectedModel !== m.id && (
                            <span title="Supports vision input">
                              <ImageIcon className="size-3 text-muted-foreground/75" />
                            </span>
                          )}
                          {selectedModel === m.id && (
                            <CheckCircle className="size-3.5 text-green-600 dark:text-green-400" />
                          )}
                        </div>
                      </button>
                    ))}
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";
import React, { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Checkbox } from "@/components/ui/checkbox";
import { Slider } from "@/components/ui/slider";
import {
  Smartphone,
  Tablet,
  Laptop,
  RefreshCw,
  Sparkles,
  Check,
  X,
  Layers,
  Gauge,
} from "lucide-react";
import Image from "next/image";
import { cn } from "@/lib/utils";

type InspirationImage = {
  id: string;
  url: string;
};

type GeneratorDialogProps = {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (
    prompt: string,
    deviceType: string,
    includeDrawing: boolean,
    selectedImageIds: string[],
    variantCount: number,
    creativeRange: number,
  ) => void;
  hasDrawings: boolean;
  projectId: string;
};

// Style Word Bank — curated design keywords inspired by Google Stitch's Redesign mode
const STYLE_CATEGORIES = [
  {
    label: "Layout",
    pills: [
      "Bento Grid",
      "Editorial",
      "Swiss Style",
      "Split-Screen",
      "Card Stack",
      "Magazine",
    ],
  },
  {
    label: "Texture",
    pills: [
      "Glassmorphism",
      "Claymorphism",
      "Skeuomorphic",
      "Neumorphism",
      "Flat",
      "Grainy",
    ],
  },
  {
    label: "Atmosphere",
    pills: [
      "Brutalist",
      "Cyberpunk",
      "Y2K",
      "Retro-Futurism",
      "Minimalist",
      "Corporate",
    ],
  },
  {
    label: "Color",
    pills: [
      "Duotone",
      "Monochromatic",
      "Pastel",
      "Dark Mode OLED",
      "Neon",
      "Earth Tones",
    ],
  },
];

export function GeneratorDialog({
  isOpen,
  onClose,
  onSubmit,
  hasDrawings,
  projectId,
}: GeneratorDialogProps) {
  const [idea, setIdea] = useState("");
  const [content, setContent] = useState("");
  const [selectedPills, setSelectedPills] = useState<string[]>([]);
  const [deviceType, setDeviceType] = useState<string>("custom");
  const [includeDrawing, setIncludeDrawing] = useState(hasDrawings);
  const [selectedImageIds, setSelectedImageIds] = useState<string[]>([]);
  const [inspirationImages, setInspirationImages] = useState<
    InspirationImage[]
  >([]);
  const [isLoadingImages, setIsLoadingImages] = useState(false);
  const [variantCount, setVariantCount] = useState(1);
  const [creativeRange, setCreativeRange] = useState(1.0);

  // Sync includeDrawing when hasDrawings changes
  useEffect(() => {
    setIncludeDrawing(hasDrawings);
  }, [hasDrawings]);

  // Load project inspiration images
  useEffect(() => {
    if (!isOpen || !projectId) return;

    async function loadInspiration() {
      setIsLoadingImages(true);
      try {
        const response = await fetch(`/api/projects/${projectId}`);
        if (response.ok) {
          const data = await response.json();
          const serverImages = (data.inspirationImages || []).map(
            (img: any) => ({
              id: img.id,
              url: `/api/uploads/${img.filePath}`,
            }),
          );
          setInspirationImages(serverImages);
          // Select all images by default
          setSelectedImageIds(serverImages.map((img: any) => img.id));
        }
      } catch (err) {
        console.error("Failed to load reference images for dialog:", err);
      } finally {
        setIsLoadingImages(false);
      }
    }

    loadInspiration();
  }, [isOpen, projectId]);

  const handleToggleImage = (id: string) => {
    setSelectedImageIds((prev) =>
      prev.includes(id) ? prev.filter((imgId) => imgId !== id) : [...prev, id],
    );
  };

  const handleTogglePill = (pill: string) => {
    setSelectedPills((prev) =>
      prev.includes(pill) ? prev.filter((p) => p !== pill) : [...prev, pill],
    );
  };

  const handleGenerate = () => {
    // Combine structured fields into a single prompt string
    const parts: string[] = [];

    if (idea.trim()) {
      parts.push(idea.trim());
    }

    if (content.trim()) {
      parts.push(`Content: ${content.trim()}`);
    }

    if (selectedPills.length > 0) {
      parts.push(`Style: ${selectedPills.join(", ")}`);
    }

    const combinedPrompt = parts.join(". ");
    onSubmit(
      combinedPrompt,
      deviceType,
      includeDrawing,
      selectedImageIds,
      variantCount,
      creativeRange,
    );
    onClose();
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent
        onEscapeKeyDown={(e) => e.preventDefault()}
        onPointerDownOutside={(e) => e.preventDefault()}
        className="z-100 min-w-2xl bg-background border-border text-foreground shadow-2xl rounded-2xl p-0 overflow-hidden max-h-[90vh] flex flex-col"
      >
        <DialogHeader className="p-6 pb-0">
          <DialogTitle className="flex items-center gap-2 text-foreground text-lg font-bold">
            <Sparkles className="w-5 h-5 text-amber-500 fill-amber-500/20" />
            AI Mockup Generator
          </DialogTitle>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto px-6 pb-2">
          <div className="space-y-5 my-4">
            {/* Idea field */}
            <div className="space-y-2">
              <Label
                htmlFor="idea"
                className="text-xs font-semibold text-muted-foreground"
              >
                What are you building? <span className="text-amber-500">*</span>
              </Label>
              <Input
                id="idea"
                placeholder="e.g. A premium fitness tracking dashboard..."
                value={idea}
                onChange={(e) => setIdea(e.target.value)}
                className="bg-muted/20 border-border focus-visible:ring-amber-500/50 text-sm text-foreground placeholder-muted-foreground rounded-xl"
              />
            </div>

            {/* Content field */}
            <div className="space-y-2">
              <Label
                htmlFor="content"
                className="text-xs font-semibold text-muted-foreground"
              >
                Content details{" "}
                <span className="text-muted-foreground/60 text-[10px] font-normal">
                  (optional)
                </span>
              </Label>
              <Textarea
                id="content"
                placeholder="Describe specific sections, data, or copy (e.g. a line graph showing weekly calories, a list of recent workouts, a motivational quote banner)..."
                value={content}
                onChange={(e) => setContent(e.target.value)}
                className="min-h-[70px] bg-muted/20 border-border focus-visible:ring-amber-500/50 text-sm text-foreground placeholder-muted-foreground rounded-xl resize-none"
              />
            </div>

            {/* Style Word Bank */}
            <div className="space-y-2.5">
              <div className="flex items-center justify-between">
                <Label className="text-xs font-semibold text-muted-foreground">
                  Style Word Bank
                </Label>
                {selectedPills.length > 0 && (
                  <button
                    type="button"
                    onClick={() => setSelectedPills([])}
                    className="text-[10px] text-muted-foreground hover:text-foreground flex items-center gap-1 transition-colors cursor-pointer"
                  >
                    <X className="w-3 h-3" />
                    Clear all
                  </button>
                )}
              </div>
              <div className="space-y-2.5">
                {STYLE_CATEGORIES.map((category) => (
                  <div key={category.label} className="space-y-1.5">
                    <span className="text-[10px] font-medium text-muted-foreground/70 uppercase tracking-wider">
                      {category.label}
                    </span>
                    <div className="flex flex-wrap gap-1.5">
                      {category.pills.map((pill) => {
                        const isSelected = selectedPills.includes(pill);
                        return (
                          <button
                            key={pill}
                            type="button"
                            onClick={() => handleTogglePill(pill)}
                            className={cn(
                              "px-2.5 py-1 rounded-full text-xs font-medium border transition-all duration-200 cursor-pointer",
                              isSelected
                                ? "border-amber-500/60 bg-amber-500/15 text-amber-500 dark:text-amber-400 shadow-[0_0_8px_rgba(245,158,11,0.1)]"
                                : "border-border bg-muted/20 text-muted-foreground hover:border-border/80 hover:text-foreground hover:bg-muted/40",
                            )}
                          >
                            {pill}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Device Preset selection */}
            <div className="space-y-2">
              <Label className="text-xs font-semibold text-muted-foreground">
                Target Screen Size
              </Label>
              <div className="grid grid-cols-4 gap-2">
                {[
                  {
                    id: "custom",
                    label: "Custom",
                    sub: "Frame Size",
                    icon: <RefreshCw className="w-3.5 h-3.5" />,
                  },
                  {
                    id: "mobile",
                    label: "Mobile",
                    sub: "375 x 812",
                    icon: <Smartphone className="w-3.5 h-3.5" />,
                  },
                  {
                    id: "tablet",
                    label: "Tablet",
                    sub: "768 x 1024",
                    icon: <Tablet className="w-3.5 h-3.5" />,
                  },
                  {
                    id: "web",
                    label: "Web",
                    sub: "1600 x 900",
                    icon: <Laptop className="w-3.5 h-3.5" />,
                  },
                ].map((preset) => (
                  <button
                    key={preset.id}
                    type="button"
                    onClick={() => setDeviceType(preset.id)}
                    className={`flex flex-col items-center justify-center p-2.5 rounded-xl border text-center transition-all duration-200 cursor-pointer ${
                      deviceType === preset.id
                        ? "border-amber-500/80 bg-amber-500/10 text-amber-600 dark:text-amber-400 font-medium"
                        : "border-border bg-muted/20 text-muted-foreground hover:border-border/80 hover:text-foreground hover:bg-muted/40"
                    }`}
                  >
                    {preset.icon}
                    <span className="text-xs mt-1.5 leading-tight">
                      {preset.label}
                    </span>
                    <span className="text-[9px] text-muted-foreground mt-0.5 leading-none">
                      {preset.sub}
                    </span>
                  </button>
                ))}
              </div>
            </div>

            {/* Variants & Creative Range */}
            <div className="space-y-3 bg-muted/10 border border-border/80 p-3.5 rounded-xl">
              {/* Variant Count */}
              <div className="space-y-2">
                <div className="flex items-center gap-2">
                  <Layers className="w-3.5 h-3.5 text-muted-foreground/60" />
                  <Label className="text-xs font-semibold text-muted-foreground">
                    Variants
                  </Label>
                  <span className="text-[10px] text-muted-foreground/70 ml-auto">
                    Generate {variantCount} design{variantCount > 1 ? "s" : ""}
                  </span>
                </div>
                <div className="flex gap-1.5">
                  {[1, 2, 3, 4, 5].map((n) => (
                    <button
                      key={n}
                      type="button"
                      onClick={() => setVariantCount(n)}
                      className={cn(
                        "flex-1 py-1.5 rounded-lg text-xs font-bold border transition-all duration-200 cursor-pointer",
                        variantCount === n
                          ? "border-amber-500/60 bg-amber-500/15 text-amber-500 dark:text-amber-400"
                          : "border-border bg-muted/20 text-muted-foreground hover:border-border/80 hover:text-foreground",
                      )}
                    >
                      {n}
                    </button>
                  ))}
                </div>
              </div>

              {/* Creative Range */}
              {variantCount > 1 && (
                <div className="space-y-2">
                  <div className="flex items-center gap-2">
                    <Gauge className="w-3.5 h-3.5 text-muted-foreground/60" />
                    <Label className="text-xs font-semibold text-muted-foreground">
                      Creative Range
                    </Label>
                  </div>
                  <Slider
                    value={[creativeRange]}
                    onValueChange={([val]) => setCreativeRange(val)}
                    min={0.5}
                    max={1.5}
                    step={0.1}
                    className="cursor-pointer"
                  />
                  <div className="flex justify-between text-[9px] text-muted-foreground/75 font-medium px-0.5">
                    <span
                      className={creativeRange <= 0.7 ? "text-amber-500" : ""}
                    >
                      Refined
                    </span>
                    <span
                      className={
                        creativeRange > 0.7 && creativeRange <= 1.2
                          ? "text-amber-500"
                          : ""
                      }
                    >
                      Balanced
                    </span>
                    <span
                      className={creativeRange > 1.2 ? "text-amber-500" : ""}
                    >
                      Creative
                    </span>
                  </div>
                </div>
              )}
            </div>

            {/* Sketch toggle (only if has drawings) */}
            {hasDrawings && (
              <div className="flex items-center space-x-2 bg-muted/10 border border-border/80 p-3 rounded-xl">
                <Checkbox
                  id="sketch-toggle"
                  checked={includeDrawing}
                  onCheckedChange={(checked) => setIncludeDrawing(!!checked)}
                  className="border-border text-amber-600 focus-visible:ring-amber-500/50 data-[state=checked]:bg-amber-600 data-[state=checked]:border-amber-600"
                />
                <div className="grid gap-1.5 leading-none">
                  <label
                    htmlFor="sketch-toggle"
                    className="text-xs font-medium text-foreground leading-none cursor-pointer"
                  >
                    Include hand-drawn layout context
                  </label>
                  <p className="text-[10px] text-muted-foreground">
                    Sends the sketch inside the frame to guide the visual
                    structure.
                  </p>
                </div>
              </div>
            )}

            {/* Inspiration / Design reference selection */}
            {inspirationImages.length > 0 && (
              <div className="space-y-2">
                <Label className="text-xs font-semibold text-muted-foreground">
                  Design References ({selectedImageIds.length}/
                  {inspirationImages.length})
                </Label>
                <div className="flex gap-2 overflow-x-auto py-1 scrollbar-thin scrollbar-thumb-muted/30">
                  {inspirationImages.map((image) => {
                    const isSelected = selectedImageIds.includes(image.id);
                    return (
                      <div
                        key={image.id}
                        onClick={() => handleToggleImage(image.id)}
                        className={`relative aspect-square w-16 h-16 rounded-lg overflow-hidden border cursor-pointer shrink-0 transition-all duration-200 ${
                          isSelected
                            ? "border-amber-500 ring-2 ring-amber-500/30"
                            : "border-border opacity-60 hover:opacity-100"
                        }`}
                      >
                        <Image
                          src={image.url}
                          alt="Design reference"
                          fill
                          className="object-cover"
                          unoptimized
                        />
                        {isSelected && (
                          <div className="absolute inset-0 bg-black/40 flex items-center justify-center">
                            <div className="bg-amber-500 rounded-full p-0.5">
                              <Check className="w-3 h-3 text-zinc-950 font-bold" />
                            </div>
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>
            )}
          </div>
        </div>

        <DialogFooter className="p-4 pt-4 flex gap-2 border-t border-border/80">
          <Button
            type="button"
            variant="ghost"
            onClick={onClose}
            className="rounded-xl border border-border bg-transparent text-muted-foreground hover:text-foreground hover:bg-muted/30 cursor-pointer"
          >
            Cancel
          </Button>
          <Button
            type="button"
            onClick={handleGenerate}
            disabled={!idea.trim() && !hasDrawings}
            className="rounded-xl bg-amber-500 text-amber-950 dark:text-zinc-950 hover:bg-amber-400 font-bold cursor-pointer disabled:opacity-50"
          >
            <Sparkles className="w-4 h-4 mr-1 fill-current" />
            Generate UI
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";
import React, { useRef } from "react";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { useChatWindow } from "@/hooks/use-canvas";
import { cn } from "@/lib/utils";
import { ChatMessage } from "@/redux/slice/chat";
import {
  Loader2,
  RefreshCw,
  Send,
  Trash2,
  X,
  Folder,
  Paperclip,
} from "lucide-react";

type Props = { generatedUIId: string; isOpen: boolean; onClose: () => void };

export default function ChatWindow({ generatedUIId, isOpen, onClose }: Props) {
  const {
    inputValue,
    setInputValue,
    scrollAreaRef,
    inputRef,
    handleSendMessage,
    handleKeyPress,
    handleClearChat,
    chatState,
  } = useChatWindow(generatedUIId, isOpen);

  if (!isOpen) return null;

  return (
    <div
      className="absolute right-0 top-0 bottom-0 w-[360px] z-60 h-full border-l border-sidebar-border bg-sidebar flex flex-col transition-all duration-300 select-none"
      style={{
        boxShadow: "-4px 0 16px rgba(0,0,0,0.02)",
      }}
    >
      {/* Header */}
      <div className="flex items-center justify-between p-5 border-b border-sidebar-border/60">
        <div className="flex items-center gap-2">
          <RefreshCw className="w-4 h-4 text-foreground/80 animate-pulse" />
          <h2 className="font-heading font-bold text-foreground text-base tracking-tight">
            Design Chat
          </h2>
        </div>
        <div className="flex items-center gap-1.5">
          {chatState?.messages && chatState.messages.length > 0 && (
            <Button
              variant="ghost"
              size="sm"
              onClick={handleClearChat}
              className="h-8 w-8 p-0 text-muted-foreground hover:text-foreground hover:bg-sidebar-accent rounded-full cursor-pointer"
              title="Clear chat"
            >
              <Trash2 className="w-4 h-4" />
            </Button>
          )}
          <Button
            variant="ghost"
            size="sm"
            onClick={onClose}
            className="h-8 w-8 p-0 text-muted-foreground hover:text-foreground hover:bg-sidebar-accent rounded-full cursor-pointer"
          >
            <X className="w-4 h-4" />
          </Button>
        </div>
      </div>

      {/* Messages */}
      <ScrollArea ref={scrollAreaRef} className="flex-1 p-5 overflow-y-auto">
        <div className="space-y-6">
          {!chatState?.messages || chatState.messages.length === 0 ? (
            <div className="text-center text-muted-foreground py-16 space-y-3">
              <RefreshCw className="w-8 h-8 mx-auto opacity-30 text-primary animate-spin-slow" />
              <p className="text-sm font-medium">Ask me to redesign this UI!</p>
              <p className="text-xs leading-relaxed opacity-80 px-4">
                I can modify layout alignments, customize colors, inject styles,
                and introduce features in real time.
              </p>
            </div>
          ) : (
            chatState.messages.map((message: ChatMessage) => {
              const isUser = message.role === "user";
              return (
                <div key={message.id} className="space-y-1.5">
                  {/* Sender Header */}
                  <div className="flex items-center justify-between">
                    <span className="text-[9px] font-bold uppercase tracking-widest text-muted-foreground">
                      {isUser ? "You" : "Claude"}
                    </span>
                    <span className="text-[9px] font-mono text-muted-foreground/60">
                      {new Date(message.timestamp).toLocaleTimeString([], {
                        hour: "2-digit",
                        minute: "2-digit",
                      })}
                    </span>
                  </div>

                  {/* Message Bubble Card */}
                  <div className="p-3 bg-card border border-sidebar-border/40 rounded-xl shadow-xs text-xs text-foreground leading-relaxed whitespace-pre-wrap">
                    {message.content}

                    {/* Model Details & Action tag */}
                    {!isUser && message.isStreaming && (
                      <div className="flex items-center gap-1.5 mt-2 text-primary font-medium">
                        <Loader2 size={10} className="animate-spin" />
                        <span className="text-[10px]">Thinking...</span>
                      </div>
                    )}
                  </div>

                  {/* Render Mock Context Tags for User Prompt */}
                  {isUser && (
                    <div className="flex flex-wrap gap-1.5 pt-1">
                      <div className="inline-flex items-center gap-1 px-2.5 py-1 text-[10px] font-medium bg-sidebar-accent border border-sidebar-border/50 text-muted-foreground rounded-md shadow-2xs hover:text-foreground transition cursor-default">
                        <Folder className="size-3 text-muted-foreground/80" />
                        <span>OpenUI design system</span>
                      </div>
                      <div className="inline-flex items-center gap-1 px-2.5 py-1 text-[10px] font-medium bg-sidebar-accent border border-sidebar-border/50 text-muted-foreground rounded-md shadow-2xs hover:text-foreground transition cursor-default">
                        <Folder className="size-3 text-muted-foreground/80" />
                        <span>openui-web</span>
                      </div>
                    </div>
                  )}
                </div>
              );
            })
          )}
        </div>
      </ScrollArea>

      {/* Input Form container */}
      <div className="p-5 border-t border-sidebar-border/60 bg-sidebar-accent/10">
        <div className="border border-sidebar-border/80 bg-card rounded-2xl p-3 focus-within:border-primary/50 focus-within:ring-2 focus-within:ring-primary/10 transition duration-200">
          <textarea
            ref={inputRef as any}
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={handleKeyPress}
            placeholder="Describe what you want to design..."
            disabled={chatState?.isStreaming}
            rows={3}
            className="w-full resize-none bg-transparent border-none outline-none text-xs text-foreground placeholder-muted-foreground/60 leading-relaxed"
          />

          {/* Action Row */}
          <div className="flex items-center justify-between mt-3 pt-2 border-t border-sidebar-border/30">
            <div className="flex items-center gap-1.5">
              <Button
                variant="ghost"
                size="sm"
                className="h-7 px-2 text-[10px] font-semibold text-muted-foreground hover:text-foreground bg-sidebar-accent/40 border border-sidebar-border/40 hover:bg-sidebar-accent rounded-lg cursor-pointer flex items-center gap-1"
                title="Attach files"
              >
                <Paperclip className="size-3" />
                Import
              </Button>
            </div>

            <Button
              onClick={handleSendMessage}
              disabled={!inputValue.trim() || chatState?.isStreaming}
              size="sm"
              className="h-7 px-3 bg-primary hover:bg-primary/95 text-primary-foreground font-semibold text-xs rounded-lg flex items-center gap-1 shadow-sm transition active:scale-95 cursor-pointer disabled:opacity-50 disabled:scale-100"
            >
              {chatState?.isStreaming ? (
                <Loader2 size={12} className="animate-spin" />
              ) : (
                <>
                  <span>Send</span>
                  <Send size={10} className="ml-0.5" />
                </>
              )}
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";
import React from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { X, Trophy, Trash2 } from "lucide-react";
import { useAppSelector, useAppDispatch } from "@/redux/store";
import { removeShape, GeneratedUIShape } from "@/redux/slice/shapes";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { parseHtmlDocument } from "@/lib/html-parser";

type ComparisonDialogProps = {
  isOpen: boolean;
  onClose: () => void;
  shapeIds: string[];
};

export default function ComparisonDialog({
  isOpen,
  onClose,
  shapeIds,
}: ComparisonDialogProps) {
  const dispatch = useAppDispatch();
  const allEntities = useAppSelector((state) => state.shapes.shapes.entities);
  const { guide } = useAppSelector((state) => state.styleGuide);

  const shapes = React.useMemo(() => {
    return shapeIds
      .map((id) => allEntities[id])
      .filter(
        (s): s is GeneratedUIShape =>
          s != null && s.type === "generatedui" && !!s.uiSpecData,
      );
  }, [shapeIds, allEntities]);

  const [layout, setLayout] = React.useState<2 | 3 | 4>(
    Math.min(shapes.length, 3) as 2 | 3 | 4,
  );

  // Resolve design tokens dynamically by title lookups
  const primaryColor = guide?.colorSections
    .find((s: { title: string }) => s.title === "Primary Colors")
    ?.swatches[0]?.hexColor || "#db2800";

  const bgColor = guide?.colorSections
    .find((s: { title: string }) => s.title === "Primary Colors")
    ?.swatches[1]?.hexColor || "#faf8f5";

  const textColor = guide?.colorSections
    .find((s: { title: string }) => s.title === "Secondary & Accent Colors")
    ?.swatches[0]?.hexColor || "#2e2925";

  const headingFont = guide?.typographySections
    .find((s: { title: string }) => s.title.toLowerCase().includes("heading") || s.title.toLowerCase().includes("headline"))
    ?.styles[0]?.fontFamily || guide?.typographySections[0]?.styles[0]?.fontFamily || "Host Grotesk";

  const bodyFont = guide?.typographySections
    .find((s: { title: string }) => s.title.toLowerCase().includes("body"))
    ?.styles[0]?.fontFamily || guide?.typographySections[1]?.styles[0]?.fontFamily || "DM Sans";

  const fontImportUrl = `https://fonts.googleapis.com/css2?family=${encodeURIComponent(headingFont)}:wght@400;700&family=${encodeURIComponent(bodyFont)}:wght@400;700&display=swap`;

  const buildSrcDoc = (html: string) => {
    const parsed = parseHtmlDocument(html);
    return `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <link href="${fontImportUrl}" rel="stylesheet" crossorigin="anonymous">
  <script src="https://cdn.tailwindcss.com"><\/script>
  <style>
    body {
      font-family: '${bodyFont}', sans-serif;
      color: ${textColor};
      margin: 0;
      padding: 0;
      overflow-y: auto;
    }
    h1,h2,h3,h4,h5,h6 { font-family: '${headingFont}', sans-serif; }
  </style>
  ${parsed.headContent}
</head>
<body class="${parsed.bodyClass}" style="${parsed.bodyStyle}">
  ${parsed.bodyContent}
</body>
</html>`;
  };

  const handlePickWinner = (winnerId: string) => {
    const losers = shapes.filter((s) => s.id !== winnerId);
    losers.forEach((s) => dispatch(removeShape(s.id)));
    toast.success(
      `Winner picked! ${losers.length} variant${losers.length !== 1 ? "s" : ""} removed.`,
    );
    onClose();
  };

  if (shapes.length < 2) return null;

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="min-w-4xl max-h-[90vh] w-full bg-background border border-border text-foreground rounded-2xl p-0 flex flex-col overflow-hidden [&>button]:hidden">
        <DialogTitle className="sr-only">Compare UI Variants</DialogTitle>
        <DialogHeader className="p-4 pb-0 shrink-0">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2 text-sm font-bold">
              <span className="text-amber-500">⚡</span>
              Compare Variants
              <span className="text-muted-foreground text-xs font-normal">
                ({shapes.length} variants)
              </span>
            </div>
            <div className="flex items-center gap-2">
              {/* Layout switcher */}
              <div className="flex items-center gap-1 bg-muted rounded-lg p-0.5">
                {([2, 3, 4] as const).map((n) => (
                  <button
                    key={n}
                    onClick={() => setLayout(n)}
                    disabled={shapes.length < n}
                    className={cn(
                      "px-2 py-1 rounded-md text-[10px] font-bold transition-all cursor-pointer",
                      layout === n
                        ? "bg-background text-foreground shadow-3xs"
                        : "text-muted-foreground hover:text-foreground",
                      shapes.length < n && "opacity-30 cursor-not-allowed",
                    )}
                  >
                    {n}-up
                  </button>
                ))}
              </div>
              <button
                onClick={onClose}
                className="p-2 rounded-md text-muted-foreground hover:text-foreground hover:bg-muted cursor-pointer"
              >
                <X size={16} />
              </button>
            </div>
          </div>
        </DialogHeader>

        <div className="flex-1 overflow-auto p-4 pt-3">
          <div
            className="grid gap-4 h-full"
            style={{
              gridTemplateColumns: `repeat(${Math.min(layout, shapes.length)}, 1fr)`,
            }}
          >
            {shapes.slice(0, layout).map((shape, i) => (
              <div
                key={shape.id}
                className="flex flex-col border border-border rounded-xl overflow-hidden bg-card"
              >
                {/* Variant header */}
                <div className="flex items-center justify-between px-3 py-2 bg-muted/50 border-b border-border/60 shrink-0">
                  <span className="text-xs font-bold text-muted-foreground">
                    Variant {i + 1}
                  </span>
                  <div className="flex items-center gap-1">
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={() => handlePickWinner(shape.id)}
                      className="h-6 px-2 text-[10px] text-amber-600 dark:text-amber-500 hover:text-amber-500 dark:hover:text-amber-400 hover:bg-amber-500/10 cursor-pointer"
                    >
                      <Trophy size={11} className="mr-1" />
                      Pick
                    </Button>
                  </div>
                </div>

                {/* Iframe preview */}
                <div className="flex-1 min-h-[400px]">
                  <iframe
                    srcDoc={buildSrcDoc(shape.uiSpecData || "")}
                    sandbox="allow-scripts allow-same-origin"
                    className="w-full h-full border-none bg-white"
                    style={{ minHeight: "400px" }}
                  />
                </div>
              </div>
            ))}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

