    <div className="flex-1 flex flex-col h-full min-h-0 overflow-hidden bg-background">
      {/* Mac-style Window Header Bar & Autosave Status */}
      <div className="flex items-center justify-between px-6 bg-card py-3 border-b border-sidebar-border/60 shrink-0">
        <div className="flex items-center gap-1.5">
          <div className="size-2.5 rounded-full bg-[#ff5f56]" />
          <div className="size-2.5 rounded-full bg-[#ffbd2e]" />
          <div className="size-2.5 rounded-full bg-[#27c93f]" />
        </div>
        <div className="flex items-center gap-1.5 text-xs text-muted-foreground/80 font-semibold">
          {isSaving ? (
            <>
              <Loader2 className="w-3.5 h-3.5 animate-spin text-primary" />
              <span>Saving...</span>
            </>
          ) : (
            <>
              <Check className="w-3.5 h-3.5 text-emerald-500" />
              <span>Saved</span>
            </>
          )}
        </div>
      </div>

      {/* Content panel: Split Screen Only */}
      <div className="grow grid grid-cols-2 gap-6 p-5 min-h-0 overflow-hidden h-full">
        {/* Left Side: Visual Editor (scrollable) */}
        <div className="h-full overflow-y-auto pr-3 scrollbar-thin scrollbar-thumb-border/40">
          {renderVisualEditor()}
        </div>

        {/* Right Side: Markdown Editor (independent scrolling) */}
        <div className="h-full flex flex-col min-h-0">
          {renderMarkdownEditor()}
        </div>
      </div>
    </div>
  );
}

"use client";
import React from "react";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { LiquidGlassButton } from "@/components/buttons/liquid-glass";
import { Paintbrush, Check, Layers, FileDown, FileUp } from "lucide-react";
import { useAppDispatch, useAppSelector } from "@/redux/store";
import {
  updateVisualTokens,
  generateMarkdownFromGuide,
  parseMarkdownToGuide,
  loadStyleGuideSuccess,
} from "@/redux/slice/style-guide";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import { downloadBlob } from "@/lib/frame-snapshot";
import { themePresets } from "@/lib/theme-presets";
import { hexToRgb, relativeLuminance } from "@/lib/contrast";

const ACCENT_PRESETS = [
  { name: "Coral", color: "#db2800" },
  { name: "Amber", color: "#F59E0B" },
  { name: "Rose", color: "#F43F5E" },
  { name: "Blue", color: "#3B82F6" },
  { name: "Emerald", color: "#10B981" },
  { name: "Violet", color: "#8B5CF6" },
  { name: "Cyan", color: "#06B6D4" },
  { name: "Fuchsia", color: "#D946EF" },
];

const RADIUS_PRESETS = [
  { label: "Sharp", value: 4 },
  { label: "Soft", value: 8 },
  { label: "Round", value: 16 },
  { label: "Full", value: 9999 },
];

const FONT_PAIRS = [
  { label: "Minimal", heading: "Host Grotesk", body: "DM Sans" },
  { label: "Modern", heading: "Inter", body: "DM Sans" },
  { label: "Elegant", heading: "Playfair Display", body: "Source Sans 3" },
  { label: "Friendly", heading: "Nunito", body: "Open Sans" },
  { label: "Technical", heading: "JetBrains Mono", body: "Inter" },
  { label: "Creative", heading: "Outfit", body: "Plus Jakarta Sans" },
  { label: "Classic", heading: "Merriweather", body: "Lato" },
  { label: "Bold", heading: "Space Grotesk", body: "Work Sans" },
];

export default function EditThemePopover() {
  const dispatch = useAppDispatch();
  const { guide } = useAppSelector((state) => state.styleGuide);

  const currentPrimary =
    guide?.colorSections[0]?.swatches[0]?.hexColor || "#db2800";
  const currentBg = guide?.colorSections[0]?.swatches[1]?.hexColor || "#faf8f5";
  const currentText =
    guide?.colorSections[1]?.swatches[0]?.hexColor || "#2e2925";
  const currentCardRadius = guide?.designSystemDetails?.cardRadius ?? 18;
  const currentHeadingFont =
    guide?.typographySections[0]?.styles[0]?.fontFamily || "Host Grotesk";
  const currentBodyFont =
    guide?.typographySections[1]?.styles[0]?.fontFamily || "DM Sans";

  const rgbBg = hexToRgb(currentBg);
  const isDarkMode = rgbBg ? relativeLuminance(rgbBg[0], rgbBg[1], rgbBg[2]) < 0.5 : false;

  const handleToggleDarkMode = (checked: boolean) => {
    if (checked) {
      // Switch to dark mode
      dispatch(
        updateVisualTokens({
          bgColor: "#121212",
          textColor: "#f5f5f5",
        }),
      );
    } else {
      // Switch to light mode
      dispatch(
        updateVisualTokens({
          bgColor: "#faf8f5",
          textColor: "#2e2925",
        }),
      );
    }
  };

  const handleAccentColor = (color: string) => {
    dispatch(updateVisualTokens({ primaryColor: color }));
  };

  const handleRadius = (value: number) => {
    dispatch(updateVisualTokens({ cardRadius: value }));
  };

  const handleFontPair = (heading: string, body: string) => {
    dispatch(updateVisualTokens({ headingFont: heading, bodyFont: body }));
  };

  const currentFontPair = FONT_PAIRS.find(
    (fp) => fp.heading === currentHeadingFont && fp.body === currentBodyFont,
  );

  const fileInputRef = React.useRef<HTMLInputElement>(null);

  const handleExportDesignMd = () => {
    if (!guide) {
      toast.error("No design system to export.");
      return;
    }
    const markdown = generateMarkdownFromGuide(guide);
    const blob = new Blob([markdown], { type: "text/markdown;charset=utf-8" });
    downloadBlob(blob, "DESIGN.md");
    toast.success("DESIGN.md exported!");
  };

  const handleImportDesignMd = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !guide) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const content = event.target?.result as string;
      if (!content) return;

      try {
        const updatedGuide = parseMarkdownToGuide(content, guide);
        dispatch(loadStyleGuideSuccess(updatedGuide));
        toast.success("DESIGN.md imported! Tokens updated.");
      } catch {
        toast.error("Failed to parse DESIGN.md. Check the format.");
      }
    };
    reader.readAsText(file);

    // Reset input so the same file can be re-imported
    e.target.value = "";
  };

  return (
    <Popover>
      <PopoverTrigger asChild>
        <LiquidGlassButton
          size="sm"
          variant="subtle"
          style={{ pointerEvents: "auto" }}
          className="shadow-2xs scale-90"
        >
          <Paintbrush size={11} />
          Theme
        </LiquidGlassButton>
      </PopoverTrigger>
      <PopoverContent
        side="top"
        align="end"
        sideOffset={8}
        className="w-72 bg-zinc-950 border-zinc-800 text-zinc-100 rounded-xl p-0 shadow-2xl"
      >
        <div className="p-4 space-y-4">
          {/* Header */}
          <div className="flex items-center justify-between">
            <h3 className="text-xs font-bold text-zinc-300 uppercase tracking-wider">
              Quick Theme
            </h3>
            <div className="h-1.5 w-1.5 rounded-full bg-amber-500 animate-pulse" />
          </div>

          {/* Theme Presets Gallery */}
          <div className="space-y-2">
            <Label className="text-[10px] font-semibold text-zinc-500 uppercase tracking-wider">
              Presets
            </Label>
            <div className="grid grid-cols-2 gap-1.5 max-h-[120px] overflow-y-auto pr-1 scrollbar-thin scrollbar-thumb-zinc-800">
              {themePresets.map((preset) => {
                const presetPrimary =
                  preset.colorSections[0]?.swatches[0]?.hexColor || "#db2800";
                const presetBg =
                  preset.colorSections[0]?.swatches[1]?.hexColor || "#faf8f5";
                const presetText =
                  preset.colorSections[1]?.swatches[0]?.hexColor || "#2e2925";
                const presetFont =
                  preset.typographySections[0]?.styles[0]?.fontFamily ||
                  "Inter";
                const isActive = guide?.theme === preset.theme;
                return (
                  <button
                    key={preset.theme}
                    type="button"
                    onClick={() => {
                      dispatch(loadStyleGuideSuccess(preset));
                      toast.success(`Applied "${preset.theme}" preset!`);
                    }}
                    className={cn(
                      "p-2 rounded-lg border text-left transition-all duration-200 cursor-pointer relative",
                      isActive
                        ? "border-amber-500/60 bg-amber-500/10"
                        : "border-zinc-800 bg-zinc-900/30 hover:border-zinc-700",
                    )}
                  >
                    <div className="flex items-center gap-1.5 mb-1">
                      <div
                        className="w-3 h-3 rounded-full border border-black/20"
                        style={{ backgroundColor: presetPrimary }}
                      />
                      <div
                        className="w-3 h-3 rounded-full border border-black/20"
                        style={{ backgroundColor: presetBg }}
                      />
                      <div
                        className="w-3 h-3 rounded-full border border-black/20"
                        style={{ backgroundColor: presetText }}
                      />
                    </div>
                    <div
                      className={cn(
                        "text-[9px] font-bold truncate",
                        isActive ? "text-amber-400" : "text-zinc-300",
                      )}
                    >
                      {preset.theme}
                    </div>
                    <div className="text-[7px] text-zinc-600 truncate">
                      {presetFont}
                    </div>
                    {isActive && (
                      <Check className="absolute top-1.5 right-1.5 w-2.5 h-2.5 text-amber-400" />
                    )}
                  </button>
                );
              })}
            </div>
          </div>

          <hr className="border-zinc-800/60" />

          {/* Light/Dark Toggle */}
          <div className="flex items-center justify-between py-1">
            <Label className="text-xs font-medium text-zinc-300">
              Dark mode
            </Label>
            <Switch
              checked={isDarkMode}
              onCheckedChange={handleToggleDarkMode}
              className="cursor-pointer data-[state=checked]:bg-amber-600"
            />
          </div>

          <hr className="border-zinc-800/60" />

          {/* Accent Color */}
          <div className="space-y-2">
            <Label className="text-[10px] font-semibold text-zinc-500 uppercase tracking-wider">
              Accent Color
            </Label>
            <div className="flex gap-2 flex-wrap">
              {ACCENT_PRESETS.map((preset) => {
                const isActive =
                  currentPrimary.toUpperCase() === preset.color.toUpperCase();
                return (
                  <button
                    key={preset.color}
                    type="button"
                    onClick={() => handleAccentColor(preset.color)}
                    title={preset.name}
                    className={cn(
                      "w-7 h-7 rounded-full border-2 transition-all duration-200 cursor-pointer flex items-center justify-center",
                      isActive
                        ? "border-white scale-110 shadow-[0_0_10px_var(--accent-glow)]"
                        : "border-transparent hover:border-zinc-600 hover:scale-105",
                    )}
                    style={
                      {
                        backgroundColor: preset.color,
                        "--accent-glow": `${preset.color}60`,
                      } as React.CSSProperties
                    }
                  >
                    {isActive && (
                      <Check className="w-3 h-3 text-white drop-shadow-md" />
                    )}
                  </button>
                );
              })}
            </div>
          </div>

          <hr className="border-zinc-800/60" />

          {/* Corner Radius */}
          <div className="space-y-2">
            <Label className="text-[10px] font-semibold text-zinc-500 uppercase tracking-wider">
              Corner Radius
            </Label>
            <div className="grid grid-cols-4 gap-1.5">
              {RADIUS_PRESETS.map((preset) => {
                const isActive = currentCardRadius === preset.value;
                return (
                  <button
                    key={preset.value}
                    type="button"
                    onClick={() => handleRadius(preset.value)}
                    className={cn(
                      "py-1.5 rounded-lg text-[10px] font-semibold border transition-all duration-200 cursor-pointer",
                      isActive
                        ? "border-amber-500/60 bg-amber-500/15 text-amber-400"
                        : "border-zinc-800 bg-zinc-900/40 text-zinc-500 hover:border-zinc-700 hover:text-zinc-400",
                    )}
                  >
                    {preset.label}
                  </button>
                );
              })}
            </div>
          </div>

          <hr className="border-zinc-800/60" />

          {/* Font Pair */}
          <div className="space-y-2">
            <Label className="text-[10px] font-semibold text-zinc-500 uppercase tracking-wider">
              Font Pair
            </Label>
            <div className="grid grid-cols-2 gap-1.5 max-h-[140px] overflow-y-auto pr-1 scrollbar-thin scrollbar-thumb-zinc-800">
              {FONT_PAIRS.map((fp) => {
                const isActive =
                  fp.heading === currentHeadingFont &&
                  fp.body === currentBodyFont;
                return (
                  <button
                    key={fp.label}
                    type="button"
                    onClick={() => handleFontPair(fp.heading, fp.body)}
                    className={cn(
                      "p-2 rounded-lg border text-left transition-all duration-200 cursor-pointer",
                      isActive
                        ? "border-amber-500/60 bg-amber-500/10"
                        : "border-zinc-800 bg-zinc-900/30 hover:border-zinc-700",
                    )}
                  >
                    <div
                      className={cn(
                        "text-[10px] font-bold truncate",
                        isActive ? "text-amber-400" : "text-zinc-300",
                      )}
                    >
                      {fp.label}
                    </div>
                    <div className="text-[8px] text-zinc-600 truncate mt-0.5">
                      {fp.heading} + {fp.body}
                    </div>
                  </button>
                );
              })}
            </div>
          </div>

          <hr className="border-zinc-800/60" />

          {/* Apply to All */}
          <button
            type="button"
            onClick={async () => {
              try {
                const urlParams = new URLSearchParams(window.location.search);
                const projectId = urlParams.get("project");
                if (!projectId || !guide) {
                  toast.error("No project or style guide found.");
                  return;
                }

                // Save the current style guide to persist changes for all screens
                const response = await fetch(
                  `/api/projects/${projectId}/style-guide`,
                  {
                    method: "PUT",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify(guide),
                  },
                );

                if (response.ok) {
                  toast.success(
                    "Theme applied to all screens! Regenerating will use the updated tokens.",
                  );
                } else {
                  toast.error("Failed to save theme. Please try again.");
                }
              } catch {
                toast.error("Failed to apply theme.");
              }
            }}
            className="w-full py-2 rounded-lg text-xs font-bold border border-amber-500/40 bg-amber-500/10 text-amber-400 hover:bg-amber-500/20 transition-all duration-200 cursor-pointer flex items-center justify-center gap-1.5"
          >
            <Layers size={12} />
            Apply to All Screens
          </button>

          {/* DESIGN.md Import / Export */}
          <div className="flex gap-1.5">
            <button
              type="button"
              onClick={handleExportDesignMd}
              className="flex-1 py-1.5 rounded-lg text-[10px] font-semibold border border-zinc-800 bg-zinc-900/40 text-zinc-400 hover:border-zinc-700 hover:text-zinc-300 transition-all duration-200 cursor-pointer flex items-center justify-center gap-1"
            >
              <FileDown size={11} />
              Export .md
            </button>
            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              className="flex-1 py-1.5 rounded-lg text-[10px] font-semibold border border-zinc-800 bg-zinc-900/40 text-zinc-400 hover:border-zinc-700 hover:text-zinc-300 transition-all duration-200 cursor-pointer flex items-center justify-center gap-1"
            >
              <FileUp size={11} />
              Import .md
            </button>
            <input
              ref={fileInputRef}
              type="file"
              accept=".md,.txt"
              onChange={handleImportDesignMd}
              className="hidden"
            />
          </div>
        </div>
      </PopoverContent>
    </Popover>
  );
}

"use client";
import React from "react";
import { Dialog, DialogContent, DialogTitle } from "@/components/ui/dialog";
import { LiquidGlassButton } from "@/components/buttons/liquid-glass";
import {
  X,
  Smartphone,
  Tablet,
  Monitor,
  ZoomIn,
  ZoomOut,
  ExternalLink,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { useAppSelector } from "@/redux/store";
import { TOKEN_LISTENER_SCRIPT } from "@/hooks/use-token-injection";
import { parseHtmlDocument } from "@/lib/html-parser";

type DeviceFrame = "phone" | "tablet" | "desktop";

const DEVICE_DIMS: Record<
  DeviceFrame,
  { w: number; h: number; label: string }
> = {
  phone: { w: 375, h: 812, label: "Phone" },
  tablet: { w: 768, h: 1024, label: "Tablet" },
  desktop: { w: 1600, h: 900, label: "Desktop" },
};

type FullscreenPreviewProps = {
  isOpen: boolean;
  onClose: () => void;
  shapeId: string;
};

export default function FullscreenPreview({
  isOpen,
  onClose,
  shapeId,
}: FullscreenPreviewProps) {
  const [device, setDevice] = React.useState<DeviceFrame>("desktop");
  const [zoom, setZoom] = React.useState(1);

  const shape = useAppSelector(
    (state) => state.shapes.shapes.entities[shapeId],
  );
  const { guide } = useAppSelector((state) => state.styleGuide);

  // Initialize and reset device frame matching based on shape width on open
  React.useEffect(() => {
    if (isOpen && shape) {
      if (shape.w < 500) {
        setDevice("phone");
      } else if (shape.w >= 500 && shape.w < 900) {
        setDevice("tablet");
      } else {
        setDevice("desktop");
      }
      setZoom(1);
    }
  }, [isOpen, shapeId, shape?.w]);

  if (!shape || shape.type !== "generatedui" || !shape.uiSpecData) return null;

  // Resolve styles dynamically by title lookups (design system guidelines compliance)
  const primaryColor =
    guide?.colorSections.find(
      (s: { title: string }) => s.title === "Primary Colors",
    )?.swatches[0]?.hexColor || "#db2800";

  const bgColor =
    guide?.colorSections.find(
      (s: { title: string }) => s.title === "Primary Colors",
    )?.swatches[1]?.hexColor || "#faf8f5";

  const textColor =
    guide?.colorSections.find(
      (s: { title: string }) => s.title === "Secondary & Accent Colors",
    )?.swatches[0]?.hexColor || "#2e2925";

  const headingFont =
    guide?.typographySections.find(
      (s: { title: string }) =>
        s.title.toLowerCase().includes("heading") ||
        s.title.toLowerCase().includes("headline"),
    )?.styles[0]?.fontFamily ||
    guide?.typographySections[0]?.styles[0]?.fontFamily ||
    "Host Grotesk";

  const bodyFont =
    guide?.typographySections.find((s: { title: string }) =>
      s.title.toLowerCase().includes("body"),
    )?.styles[0]?.fontFamily ||
    guide?.typographySections[1]?.styles[0]?.fontFamily ||
    "DM Sans";

  const buttonRadius = guide
    ? `${guide.designSystemDetails.buttonRadius}px`
    : "9999px";
  const fontImportUrl = `https://fonts.googleapis.com/css2?family=${encodeURIComponent(headingFont)}:wght@400;700&family=${encodeURIComponent(bodyFont)}:wght@400;700&display=swap`;

  const dims = DEVICE_DIMS[device];

  const parsed = parseHtmlDocument(shape.uiSpecData);

  // Reconstruct original generated HTML layout by mapping bodyClass/bodyStyle directly on body,
  // letting user's mockup center or stretch natively without forced overrides
  const srcDocContent = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <link href="${fontImportUrl}" rel="stylesheet" crossorigin="anonymous">
  <script src="https://cdn.tailwindcss.com"><\/script>
  <style>
    :root {
      --color-primary: ${primaryColor};
      --color-secondary: ${bgColor};
      --color-text: ${textColor};
      --font-heading: '${headingFont}', sans-serif;
      --font-body: '${bodyFont}', sans-serif;
      --border-radius-button: ${buttonRadius};
    }
    body {
      font-family: var(--font-body);
      color: var(--color-text);
      margin: 0;
      padding-top: ${device === "phone" ? "32px" : "16px"};
      overflow-y: auto;
    }
    h1, h2, h3, h4, h5, h6 {
      font-family: var(--font-heading);
    }
  </style>
  ${parsed.headContent}
</head>
<body class="${parsed.bodyClass}" style="${parsed.bodyStyle}">
  ${parsed.bodyContent}
  ${TOKEN_LISTENER_SCRIPT}
</body>
</html>`;

  const handleZoomIn = () => setZoom((z) => Math.min(z + 0.25, 2));
  const handleZoomOut = () => setZoom((z) => Math.max(z - 0.25, 0.25));

  const handleOpenNewTab = () => {
    const fonts = {
      headingFont:
        guide?.typographySections?.[0]?.styles?.[0]?.fontFamily ||
        "Host Grotesk",
      bodyFont:
        guide?.typographySections?.[1]?.styles?.[0]?.fontFamily || "DM Sans",
    };
    const families = new Set<string>();
    families.add(fonts.headingFont.replace(/\s+/g, "+"));
    families.add(fonts.bodyFont.replace(/\s+/g, "+"));
    families.add("Inter");
    const params = Array.from(families)
      .map((f) => `family=${f}:wght@400;500;600;700`)
      .join("&");
    const fontsUrl = `https://fonts.googleapis.com/css2?${params}&display=swap`;

    const fullDocument = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>OpenUI Preview - Standalone</title>
  <script src="https://cdn.tailwindcss.com"></script>
  <link href="${fontsUrl}" rel="stylesheet">
  <style>
    :root {
      --color-primary: ${primaryColor};
      --color-secondary: ${bgColor};
      --color-text: ${textColor};
      --font-heading: '${headingFont}', sans-serif;
      --font-body: '${bodyFont}', sans-serif;
      --border-radius-button: ${buttonRadius};
    }
    body {
      font-family: '${fonts.bodyFont}', 'Inter', sans-serif;
      margin: 0;
      padding: 0;
      color: var(--color-text);
      background-color: var(--color-secondary);
    }
    h1, h2, h3, h4, h5, h6 {
      font-family: '${fonts.headingFont}', 'Inter', sans-serif;
    }
    [data-generated-ui] {
      width: 100%;
      display: flex;
      flex-direction: column;
      align-items: center;
    }
  </style>
  ${parsed.headContent}
</head>
<body class="${parsed.bodyClass}" style="${parsed.bodyStyle}">
  ${parsed.bodyContent}
</body>
</html>`;

    const blob = new Blob([fullDocument], { type: "text/html;charset=utf-8" });
    const blobUrl = URL.createObjectURL(blob);
    window.open(blobUrl, "_blank");
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="max-w-none sm:max-w-none max-h-none sm:max-h-none w-screen h-screen bg-zinc-950 border-none rounded-none p-0 flex flex-col overflow-hidden [&>button]:hidden">
        <DialogTitle className="sr-only">Fullscreen Preview</DialogTitle>
        {/* Toolbar */}
        <div className="flex items-center justify-between px-6 py-3 bg-zinc-900/80 border-b border-zinc-800/60 shrink-0">
          <div className="flex items-center gap-2">
            <span className="text-xs font-bold text-zinc-400 uppercase tracking-wider">
              Preview
            </span>
            <span className="text-[10px] text-zinc-600 bg-zinc-800/50 px-2 py-0.5 rounded-full">
              {dims.w} × {dims.h}
            </span>
          </div>

          {/* Device Switcher */}
          <div className="flex items-center gap-1 bg-zinc-800/50 rounded-full p-0.5">
            {[
              { id: "phone" as DeviceFrame, icon: Smartphone },
              { id: "tablet" as DeviceFrame, icon: Tablet },
              { id: "desktop" as DeviceFrame, icon: Monitor },
            ].map(({ id, icon: Icon }) => (
              <button
                key={id}
                onClick={() => {
                  setDevice(id);
                  setZoom(1);
                }}
                className={cn(
                  "p-2 rounded-full transition-all cursor-pointer",
                  device === id
                    ? "bg-zinc-700 text-zinc-100"
                    : "text-zinc-500 hover:text-zinc-300",
                )}
                title={DEVICE_DIMS[id].label}
              >
                <Icon size={14} />
              </button>
            ))}
          </div>

          {/* Zoom + Close */}
          <div className="flex items-center gap-2">
            {device === "desktop" && (
              <LiquidGlassButton
                size="sm"
                variant="subtle"
                onClick={handleOpenNewTab}
                className="shadow-2xs text-[11px] h-7 px-2.5 mr-2 bg-zinc-800/80 hover:bg-zinc-700/80 border-zinc-700 text-zinc-300 hover:text-zinc-100 cursor-pointer"
              >
                <ExternalLink size={12} className="mr-1.5 inline-block" />
                Open in New Tab
              </LiquidGlassButton>
            )}
            <div className="flex items-center gap-1 bg-zinc-800/50 rounded-full p-0.5">
              <button
                onClick={handleZoomOut}
                className="p-1.5 rounded-full text-zinc-500 hover:text-zinc-300 cursor-pointer"
              >
                <ZoomOut size={13} />
              </button>
              <span className="text-[10px] text-zinc-400 font-mono min-w-[3ch] text-center">
                {Math.round(zoom * 100)}%
              </span>
              <button
                onClick={handleZoomIn}
                className="p-1.5 rounded-full text-zinc-500 hover:text-zinc-300 cursor-pointer"
              >
                <ZoomIn size={13} />
              </button>
            </div>
            <button
              onClick={onClose}
              className="p-2 rounded-full text-zinc-500 hover:text-zinc-200 hover:bg-zinc-800 transition-all cursor-pointer"
            >
              <X size={16} />
            </button>
          </div>
        </div>

        {/* Preview Area */}
        <div className="flex-1 flex overflow-auto bg-zinc-950 px-4 pb-2">
          {/* Scaled wrapper to handle accurate sizing in flow layout without scrollbar quirks */}
          <div
            className={cn(
              "transition-all duration-300 flex items-center justify-center shrink-0 m-auto",
              device === "desktop" ? "w-full h-full" : "",
            )}
            style={{
              width: device === "desktop" ? "100%" : dims.w * zoom,
              height: device === "desktop" ? "100%" : dims.h * zoom,
            }}
          >
            <div
              className={cn(
                "relative transition-all duration-300 shadow-2xl origin-center shrink-0",
                device === "phone" &&
                  "rounded-[2.5rem] border-8 border-zinc-700 bg-zinc-800",
                device === "tablet" &&
                  "rounded-3xl border-[6px] border-zinc-700 bg-zinc-800",
                device === "desktop" &&
                  "rounded-xl border-2 border-zinc-700 bg-zinc-800 overflow-hidden flex flex-col w-full h-full",
              )}
              style={{
                width: device === "desktop" ? "100%" : dims.w,
                height: device === "desktop" ? "100%" : dims.h,
                transform: device === "desktop" ? undefined : `scale(${zoom})`,
              }}
            >
              {/* Desktop browser chrome */}
              {device === "desktop" && (
                <div className="flex items-center gap-2 px-4 py-2 bg-zinc-800 border-b border-zinc-700/60 shrink-0">
                  <div className="flex gap-1.5">
                    <div className="w-2.5 h-2.5 rounded-full bg-red-500/70" />
                    <div className="w-2.5 h-2.5 rounded-full bg-yellow-500/70" />
                    <div className="w-2.5 h-2.5 rounded-full bg-green-500/70" />
                  </div>
                  <div className="flex-1 mx-4">
                    <div className="h-5 bg-zinc-700/60 rounded-md max-w-md mx-auto flex items-center justify-center">
                      <span className="text-[9px] text-zinc-500 font-mono">
                        localhost:3000
                      </span>
                    </div>
                  </div>
                </div>
              )}

              <iframe
                data-openui-shape={`fullscreen-${shapeId}`}
                srcDoc={srcDocContent}
                sandbox="allow-scripts allow-same-origin"
                className={cn(
                  "w-full bg-white",
                  device === "desktop" && "flex-1",
                )}
                style={{
                  height:
                    device === "desktop"
                      ? undefined // Subtract browser chrome height
                      : device === "phone"
                        ? dims.h - 16 // Subtract notch area padding
                        : dims.h - 12,
                  border: "none",
                }}
              />

              {/* Phone home indicator */}
              {device === "phone" && (
                <div className="absolute bottom-2 left-1/2 -translate-x-1/2 w-[100px] h-[4px] bg-zinc-600 rounded-full" />
              )}
            </div>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

